    /// Execution control and limits (code execution, timeouts, iteration caps).
    /// </summary>
    [JsonPropertyName("execution")]
    public ExecutionCapabilities? Execution { get; set; }

    /// <summary>
    /// Human-in-the-loop support (approvals, interventions, feedback).
    /// </summary>
    [JsonPropertyName("humanInTheLoop")]
    public HumanInTheLoopCapabilities? HumanInTheLoop { get; set; }

    /// <summary>
    /// Integration-specific capabilities not covered by the standard
    /// categories. Open by key: any JSON value is allowed under a key, because
    /// the categories above cannot anticipate what an integration declares.
    /// </summary>
    [JsonPropertyName("custom")]
    public JsonElement? Custom { get; set; }
}

/// <summary>
/// Why a run ended.
/// </summary>
[JsonConverter(typeof(RunFinishedOutcomeJsonConverter))]
public abstract class RunFinishedOutcome
{
    internal RunFinishedOutcome() { }

    [JsonPropertyName("type")]
    public abstract string Type { get; }
}

/// <summary>
/// The run completed. Equivalent to an absent outcome. Closed like every other
/// object, which is also what keeps it from carrying the suspended sibling's
/// interrupts — a success with an interrupt still pending would be a
/// contradiction, not an extension.
/// </summary>
public sealed class RunFinishedSuccessOutcome : RunFinishedOutcome
{
    /// <summary>
    /// Discriminator.
    /// </summary>
    [JsonPropertyName("type")]
    public override string Type => RunFinishedOutcomeTypes.Success;
}

/// <summary>
/// The run is paused, waiting for something outside it. Resuming means starting
/// a new run whose resume entries answer these interrupts.
/// </summary>
public sealed class RunFinishedInterruptOutcome : RunFinishedOutcome
{
    /// <summary>
    /// Discriminator.
    /// </summary>
    [JsonPropertyName("type")]
    public override string Type => RunFinishedOutcomeTypes.Interrupt;

    /// <summary>
    /// What the run is waiting for. At least one: an interrupt outcome with
    /// nothing to answer would leave a consumer with nothing to do.
    /// </summary>
    [JsonPropertyName("interrupts")]
    public IList<AGUIInterrupt> Interrupts { get; set; } = [];
}

/// <summary>
/// Why a subagent's segment of a run ended. Mirrors RunFinishedOutcome one
/// level down.
/// </summary>
[JsonConverter(typeof(SubagentFinishedOutcomeJsonConverter))]
public abstract class SubagentFinishedOutcome
{
    internal SubagentFinishedOutcome() { }

    [JsonPropertyName("type")]
    public abstract string Type { get; }
}

/// <summary>
/// The subagent completed its work. Equivalent to an absent outcome.
/// </summary>
public sealed class SubagentFinishedSuccessOutcome : SubagentFinishedOutcome
{
    /// <summary>
    /// Discriminator.
    /// </summary>
    [JsonPropertyName("type")]
    public override string Type => SubagentFinishedOutcomeTypes.Success;
}

/// <summary>
/// The subagent is paused awaiting outside input. Terminal for this stream, not
/// for the subagent: a later run may continue the same invocation once the
/// interrupts are answered.
/// </summary>
public sealed class SubagentFinishedSuspendedOutcome : SubagentFinishedOutcome
{
    /// <summary>
    /// Discriminator.
    /// </summary>
    [JsonPropertyName("type")]
    public override string Type => SubagentFinishedOutcomeTypes.Suspended;

    /// <summary>
    /// The run-level interrupts this subagent raised itself. May be empty or
    /// absent: a subagent suspended because a descendant interrupted owns no
    /// interrupt of its own.
    /// </summary>
    [JsonPropertyName("interruptIds")]
    public IList<string>? InterruptIds { get; set; }
}

